sql.where:
coalesce(ends_at, starts_at) >= #{now}
and kind = #{kind}
and format = #{format}

    and (lower(title) like concat('%', lower(#{q}), '%')
      or lower(host) like concat('%', lower(#{q}), '%')
      or lower(location) like concat('%', lower(#{q}), '%')
      or lower(description) like concat('%', lower(#{q}), '%'))

mapper.select:
select * from events

order by starts_at, id
limit #{pageSize} offset #{offset}
